import http from 'node:http';

const menu = [{ id: 1, nama: 'Kopi' }];
function kirimJson(res, status, data, header = {}) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', ...header });
  res.end(JSON.stringify(data));
}
const rute = {
  '/menu': { GET: (req, res) => kirimJson(res, 200, menu) },
  '/sehat': { GET: (req, res) => kirimJson(res, 200, { status: 'ok' }) },
};
const server = http.createServer((req, res) => {
  const { pathname } = new URL(req.url, `http://${req.headers.host}`);
  const jalur = rute[pathname];
  if (!jalur) return kirimJson(res, 404, { error: 'Tidak ditemukan' });
  const penangan = jalur[req.method];
  if (!penangan) {
    return kirimJson(res, 405, { error: 'Method tidak didukung' }, { Allow: Object.keys(jalur).join(', ') });
  }
  penangan(req, res);
});
server.listen(3000);

const uji = [['GET', '/menu'], ['DELETE', '/menu'], ['GET', '/kasir']];
for (const [method, jalur] of uji) {
  const r = await fetch('http://localhost:3000' + jalur, { method });
  console.log(method, jalur, r.status, r.headers.get('allow'));
}
server.close();

