import http from 'node:http';
const rute = {
  'GET /menu': (req, res) => res.end('Daftar menu'),
  'POST /pesanan': (req, res) => {
    res.statusCode = 201;
    res.end('Pesanan dibuat');
  },
};
const server = http.createServer((req, res) => {
  const { pathname } = new URL(req.url, `http://${req.headers.host}`);
  const penangan = rute[`${req.method} ${pathname}`];
  if (penangan) return penangan(req, res);
  const adaJalur = Object.keys(rute).some((k) => k.split(' ')[1] === pathname);
  if (adaJalur) {
    res.statusCode = 405;
    return res.end('Method tidak didukung');
  }
  res.statusCode = 404;
  res.end('Tidak ditemukan');
});
server.listen(3000);
const r = await fetch('http://localhost:3000/menu');
console.log(r.status, await r.text());
const r2 = await fetch('http://localhost:3000/pesanan', { method: 'POST' });
console.log(r2.status, await r2.text());
const r3 = await fetch('http://localhost:3000/menu', { method: 'DELETE' });
console.log(r3.status, await r3.text());
server.close();

