import http from 'node:http';
const rute = { 'GET /halo': (req, res) => res.end('hai') };
const server = http.createServer((req, res) => {
  const { pathname } = new URL(req.url, `http://${req.headers.host}`);
  const p = rute[`${req.method} ${pathname}`];
  if (p) return p(req, res);
  res.statusCode = 404;
  res.end();
});
server.listen(3000);
const a = await fetch('http://localhost:3000/halo');
const b = await fetch('http://localhost:3000/lain');
console.log(a.status, b.status);
server.close();
